// Some portions generated by Claude
import assert from 'node:assert/strict';
import test from 'node:test';
import {edgeGeometry, graphNodeSize, edgeLabelSize, placeEdgeLabels, boxIntersectionArea} from '../../../main/frontend/graph-explorer/graph-geometry.ts';

function fixture(offset = 0, count = 1) {
  const graph = {revision: 1, nodes: [{id: 'a', label: 'Left', kind: 'iri', x: offset + 250, y: offset + 250},
    {id: 'b', label: 'Right', kind: 'iri', x: offset + 500, y: offset + 250}],
    edges: Array.from({length: count}, (_, i) => ({id: 'e' + i, source: 'a', target: 'b', predicate: 'urn:p' + i, label: 'A descriptive property ' + i}))};
  const curves = new Map(graph.edges.map(e => [e.id, edgeGeometry(graph.nodes[0], graph.nodes[1], 0)]));
  return {graph, curves};
}

test('edge labels are translation invariant in an unbounded graph world', () => {
  const a = fixture(), b = fixture(10000);
  const before = placeEdgeLabels(a.graph, a.curves), after = placeEdgeLabels(b.graph, b.curves);
  for (const [id, old] of before) {
    const next = after.get(id);
    assert.ok(Math.abs(next.point.x - old.point.x - 10000) < 1e-6);
    assert.ok(Math.abs(next.point.y - old.point.y - 10000) < 1e-6);
  }
});

test('dense parallel edge labels do not cover nodes or each other', () => {
  const {graph, curves} = fixture(10000, 12);
  const labels = placeEdgeLabels(graph, curves), accepted = [];
  assert.ok(labels.size > 0, 'some readable labels must remain');
  for (const edge of graph.edges) {
    const p = labels.get(edge.id); if (!p) continue;
    const box = {...p.point, ...edgeLabelSize(edge)};
    for (const node of graph.nodes) assert.equal(boxIntersectionArea(box, {...node, ...graphNodeSize(node)}, 0), 0);
    for (const other of accepted) assert.equal(boxIntersectionArea(box, other, 0), 0);
    accepted.push(box);
  }
});
